mapper.select:
select o.id, o.user_id, o.product_id, o.product_name, o.product_image, o.score, o.contact, o.status + 0 as status, o.remark, o.in_time, o.update_time, u.username from exchange_order o left join user u on o.user_id = u.id
and o.status = #{status}
and u.username = #{username}
order by o.id desc
